// src/Settings.jsx
import React, { useContext, useState } from 'react';
import { ThemeContext } from './ThemeContext';   // New
import './Settings.css';

export default function Settings() {
  const { theme, toggleTheme } = useContext(ThemeContext);
  const [saved, setSaved] = useState(false);

  // Mobile‑friendly save button handler
  const handleSave = () => {
    // Simulate async save
    setTimeout(() => setSaved(true), 200);
  };

  return (
    <div className={`settings-page ${theme}`}>
      <h2>Settings</h2>

      {/* Dark‑mode toggle – kept inside the page, not the header */}
      <label className="dark-mode-switch">
        Dark Mode
        <input
          type="checkbox"
          checked={theme === 'dark'}
          onChange={toggleTheme}
        />
        <span className="slider"></span>
      </label>

      {/* Other settings fields here */}

      {/* Save button – works on mobile (fixed padding & flex) */}
      <button
        className="save-btn"
        onClick={handleSave}
        disabled={saved}
      >
        {saved ? 'Saved!' : 'Save Changes'}
      </button>
    </div>
  );
}
```

**ThemeContext (new file)**

```tsx
// src/ThemeContext.jsx
import React, { createContext, useState } from 'react';

export const ThemeContext = createContext({
  theme: 'light',
  toggleTheme: () => {}
});

export const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState('light');
  const toggleTheme = () =>
    setTheme(prev => (prev === 'light' ? 'dark' : 'light'));

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};
```

